@Service
@Transactional(readOnly = true)
@RequiredArgsConstructor
public class MemberQueryService {

    private final MemberRepository memberRepository;

    public PageResponse<MemberTeamDto> search(MemberSearchCondition cond,
                                              Pageable pageable) {
        return PageResponse.of(memberRepository.searchPage(cond, pageable));
    }

    @Transactional
    public Long join(String username, int age) {
        return memberRepository.save(new Member(username, age)).getId();
    }
}

@RestController
@RequiredArgsConstructor
public class MemberFinalController {

    private final MemberQueryService service;

    @GetMapping("/final/members")
    public PageResponse<MemberTeamDto> search(MemberSearchCondition cond,
                                              Pageable pageable) {
        return service.search(cond, pageable);
    }
}

